using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"🔬 Research Agent Starting...");
Console.WriteLine($"📋 Topic: {topic}\n");

// --- Build the AI client with tools ---
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Tool instances ---
var notes = new NoteTaker();
var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch.SearchAsync),
        AIFunctionFactory.Create(notes.TakeNote),
        AIFunctionFactory.Create(notes.GetNotes),
    ]
};

// --- Agent loop ---
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to research the given topic thoroughly.
        1. Use the web_search tool to find relevant information (perform 2-3 searches with different queries).
        2. Use the take_note tool to record key findings as you go.
        3. After gathering enough information, use get_notes to review what you've collected.
        4. Finally, provide a comprehensive summary of your research findings.
        Be methodical and thorough.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
];

Console.WriteLine("🤖 Agent is researching...\n");

var response = await chatClient.GetResponseAsync(messages, tools);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("📝 RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n═══════════════════════════════════════════");
Console.WriteLine($"📌 Notes collected: {notes.NoteCount}");
Console.WriteLine("═══════════════════════════════════════════");

// --- Tools ---

/// <summary>Simulates web search results for research.</summary>
static class WebSearch
{
    [Description("Search the web for information on a given query. Returns relevant search results.")]
    public static Task<string> SearchAsync([Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        // In production, replace with a real search API (Bing, Google, etc.)
        var result = $"""
            Search results for: "{query}"

            1. [Wikipedia] Overview article covering key aspects of {query}.
               Summary: Provides foundational information and recent developments related to {query}.

            2. [Research Paper - 2025] "Advances in {query}" - A comprehensive review
               Summary: Recent peer-reviewed research highlighting breakthroughs and current state of the art.

            3. [News Article - 2026] Latest developments in {query}
               Summary: Reports on the most recent progress, industry applications, and future outlook.

            4. [Technical Blog] Deep dive into {query} - practical implications
               Summary: Expert analysis of real-world applications and emerging trends.
            """;

        return Task.FromResult(result);
    }
}

/// <summary>Allows the agent to take and retrieve notes during research.</summary>
class NoteTaker
{
    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Record a research note or key finding for later reference.")]
    public string TakeNote([Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} recorded.");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        var result = string.Join('\n', _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
        Console.WriteLine($"  📋 Retrieved {_notes.Count} notes.");
        return result;
    }
}

